class AudioController {
    constructor() {
        this.sounds = {};
        this.bgmIdle = null;
        this.bgmPlay = null;
        this.BGM_MAX_VOL = 1;
        this.FADE_TIME = 1.5;
        this.isMuted = false;
        this.isBGIdlePlaying = false;
    }

    init() {
        const source = nc.sounds;
        if (!source) return;

        const soundNames = [
            "1_bgm_idle",
            "2_bgm_play",
            "3_pop_up_appearance",
            "4_pop_up_disappearance",
            "5_main_button",
            "6_prizemap_anim",
            "7_enter_gameplay",
            "8_counter",
            "9_button_gameplay",
            "10_claw_horizontal",
            "11_claw_stop",
            "12_prize_highlight",
            "13_claw_vertical",
            "14_claw_closes",
            "15_anticipation",
            "16_get_prize",
            "17_youwon_banner",
            "18_button_reveal",
            "19_mystery_reveal",
            "20_mystery_anticipation",
            "21_mystery_drop",
            "22_mystery_winbanner"
        ];

        soundNames.forEach(name => {
            if (source[name]) this.sounds[name] = source[name];
        });

        this.bgmIdle = this.sounds["1_bgm_idle"];
        this.bgmPlay = this.sounds["2_bgm_play"];

        this.playIdleBGM();
    }

    playIdleBGM() {
        if (!this.bgmIdle) return;
        this.bgmIdle.stop();
        this.bgmIdle.loop = true;
        this.bgmIdle.play(this.BGM_MAX_VOL, true);
        this.isBGIdlePlaying = true;
    }

    stopIdleBGM() {
        if (this.bgmIdle) this.bgmIdle.stop();
        this.isBGIdlePlaying = false;
    }

    playPlayBGM() {
        if (!this.bgmPlay) return;
        this.stopIdleBGM();
        this.bgmPlay.stop();
        this.bgmPlay.loop = true;
        this.bgmPlay.play(this.BGM_MAX_VOL, true);
        this.isBGIdlePlaying = false;
    }

    stopPlayBGM(slowFade = false) {
        if (!this.bgmPlay) return;
        if (slowFade && this.bgmPlay.mainVolume && this.bgmPlay.swoopVolume) {
            this.bgmPlay.swoopVolume(0, this.FADE_TIME);
            setTimeout(() => this.bgmPlay.stop(), this.FADE_TIME * 1000);
        } else {
            this.bgmPlay.stop();
        }
        this.isBGIdlePlaying = false;
    }

    playSFX(name) {
        const sfx = this.sounds[name];
        if (sfx) {
            sfx.playOnce(); 
        }
    }
    
    playMoveSFX(name) {
        const sfx = this.sounds[name];
        if (sfx) {
            sfx.stop();
            sfx.loop = true;
            sfx.play(1.0, true);
        }
    }

    stopSFX(name) {
        if (this.sounds[name]) this.sounds[name].stop();
    }
    

    mute() {
        this.isMuted = true;

        // Mute all BGM tracks
        if (this.bgmIdle && this.bgmIdle.mainVolume) {
            if (this.bgmIdle.swoopVolume) {
                this.bgmIdle.swoopVolume(0, 0.2);
            } else {
                this.bgmIdle.mainVolume = 0;
            }
        }

        if (this.bgmPlay && this.bgmPlay.mainVolume) {
            if (this.bgmPlay.swoopVolume) {
                this.bgmPlay.swoopVolume(0, 0.2);
            } else {
                this.bgmPlay.mainVolume = 0;
            }
        }

        // Mute all SFX
        Object.values(this.sounds).forEach(sound => {
            if (sound && sound.mainVolume) {
                if (sound.swoopVolume) {
                    sound.swoopVolume(0, 0.1);
                } else {
                    sound.mainVolume = 0;
                }
            }
        });
    }

    unmute() {
        this.isMuted = false;

        // Restore BGM volume
        if (this.bgmIdle && this.isBGIdlePlaying) {
            if (this.bgmIdle.swoopVolume) {
                this.bgmIdle.swoopVolume(this.BGM_MAX_VOL, 0.2);
            } else if (this.bgmIdle.mainVolume) {
                this.bgmIdle.mainVolume = this.BGM_MAX_VOL;
            }
        }

        if (this.bgmPlay && !this.isBGIdlePlaying) {
            if (this.bgmPlay.swoopVolume) {
                this.bgmPlay.swoopVolume(this.BGM_MAX_VOL, 0.2);
            } else if (this.bgmPlay.mainVolume) {
                this.bgmPlay.mainVolume = this.BGM_MAX_VOL;
            }
        }

        // Restore SFX volume (they'll be at full volume when played next)
        Object.values(this.sounds).forEach(sound => {
            if (sound && sound.mainVolume) {
                if (sound.swoopVolume) {
                    sound.swoopVolume(1, 0.1);
                } else if (sound.mainVolume) {
                    sound.mainVolume = 1;
                }
            }
        });
    }

    toggleMute()
    {
        if(this.isMuted){
            this.unmute();
        }else{
            this.mute();
        }
        console.log(`Mute toggled. isMuted: ${this.isMuted}`);
    }
}
class DashboardController {
    constructor() {
        this.meters = {
            balance: { name: "balanceDigit", value: "$200.00", placeholders: [] },
            win:     { name: "winDigit",     value: "$0.00",   placeholders: [] },
            bet:     { name: "betDigit",     value: "$6.00",   placeholders: [] }
        };
        
        this.NUM_DIGITS = 8; 
        this.SCALE_FACTOR = 0.6; 
        this.BASE_WIDTH = 50;    
        this.SPACING = this.BASE_WIDTH * this.SCALE_FACTOR; 
        this.DOT_Y_POSITION = -16; 
        this.DEFAULT_Y_POSITION = 0;

        this.menuButton = null;
        this.menuPanel = pr.dashboard.descendantsByName.menuPanel;
        this.menuHelpPageButton = pr.dashboard.descendantsByName.helpPage_btn;
        this.menuVolumeButton = pr.dashboard.descendantsByName.volume_btn;
        this.menuReturnToLobby = pr.dashboard.descendantsByName.returnToLobby_btn;

        this.menuHelpPageButton.addReleaseCallback(this, "onShowHelpPage");
        this.menuVolumeButton.addReleaseCallback(this, "onVolumeTweak");
        this.menuHelpPageButton.addReleaseCallback(this, "onReturnToLobby");
        this.dirButtonWinGlow = [];
    }

    init() {
        this.menuButton = pr.dashboard.descendantsByName.menuButton;
        if (this.menuButton && typeof this.menuButton.addReleaseCallback === 'function') {
            this.menuButton.addPressCallback(this, "onMenuButtonPress");
            this.menuButton.addReleaseCallback(this, "onMenuButtonRelease");
        }
        if (!this.dashboardFrame || !this.dashboardFrame.spriteSetter){
            this.dashboardFrame = pr.dashboard.descendantsByName.dashboardGoldFrame;
            this.dashboardFrame.configureSpriteSetter(nc.graphicAssets.gold_frame_shine_000, 30);
        }
        this.onPlayDashboardGoldFrameGlow();

        Object.keys(this.meters).forEach(key => {
            const meter = this.meters[key];
            const container = (pr.dashboard && pr.dashboard.descendantsByName) ? 
                              pr.dashboard.descendantsByName[meter.name] : null;
            
            if (container) {
                this.spawnDigits(container, meter.placeholders, meter.name);
            }
            this.updateDisplay(key, meter.value);
        });
    }

    onMenuButtonPress() {
        pr.audioController.playSFX("5_main_button");
        this.menuButton.graphicAsset = nc.graphicAssets.menu_button_inactive;
        // this.menuButton.scale.x = this.menuButton.scale.y = 1.1;

        // if (this.menuButton.scale.swoop) {
        //     this.menuButton.scale.swoop.all(1, 0.15);
        // }
    }

    onMenuButtonRelease() {
        this.menuButton.graphicAsset = nc.graphicAssets.menu_button_active;
        this.onToggleMenuPanel();
        // this.menuButton.scale.x = this.menuButton.scale.y = 1.0;
    }

    onToggleMenuPanel()
    {
        this.menuPanel.enabled = !this.menuPanel.enabled;
    }

    setDashboardButtonsActive(isActive) {
        this.setButtonState(this.menuButton, isActive, "menu_button_active", "menu_button_inactive");
    }

    setButtonState(btn, isActive, activeName, inactiveName) {
        if (!btn) return;

        btn.buttonActive = isActive;
        const targetName = isActive ? activeName : inactiveName;
        const targetAsset = nc.graphicAssets[targetName] || nc.assets[targetName];

        if (targetAsset) {
            if (typeof btn.setGraphicAsset === 'function') {
                btn.setGraphicAsset(targetAsset);
            } else {
                btn.texture = targetAsset;
            }
            if (btn.updateGraphic) btn.updateGraphic();
        }
    }

    spawnDigits(container, placeholderArray, baseName) {
        const totalBlockWidth = (this.NUM_DIGITS - 1) * this.SPACING;
        const startX = -(totalBlockWidth / 2);
        for (let i = 0; i < this.NUM_DIGITS; i++) {
            const digitName = `${baseName}_D${i}`;
            const asset = nc.graphicAssets.cb_num_0 || nc.assets.cb_num_0;
            let newDigit = new GraphicObject(asset, container, digitName);
            newDigit.scale.x = newDigit.scale.y = this.SCALE_FACTOR;
            newDigit.position.x = startX + (i * this.SPACING);
            newDigit.position.y = this.DEFAULT_Y_POSITION;
            newDigit.colorMultiply.alpha = 0; 
            placeholderArray.push(newDigit);
        }
    }

    getAssetForChar(char) {
        let assetName = "";
        if (/\d/.test(char)) assetName = `cb_num_${char}`;
        else if (char === ".") assetName = "cb_dot";
        else if (char === "$") assetName = "cb_dollar";
        else return null; 
        
        return nc.graphicAssets?.[assetName] || nc.assets?.[assetName];
    }

    updateDisplay(meterKey, valueString) {
        const meter = this.meters[meterKey];
        if (!meter) return;
        
        meter.value = valueString; 
        
        this.renderValue(meter.placeholders, valueString);
    }

    renderValue(placeholders, valueString) {
        const chars = valueString.split("");
        let displayOffset = Math.floor((this.NUM_DIGITS - chars.length) / 2);
        placeholders.forEach(p => {
            p.colorMultiply.alpha = 0;
            p.position.y = this.DEFAULT_Y_POSITION;
        });
        for (let i = 0; i < chars.length; i++) {
            let char = chars[i];
            let pIndex = displayOffset + i;
            let placeholder = placeholders[pIndex];
            if (placeholder) {
                const tex = this.getAssetForChar(char);
                if (tex) {
                    if (typeof placeholder.setGraphicAsset === 'function') placeholder.setGraphicAsset(tex);
                    else placeholder.texture = tex;
                    placeholder.position.y = (char === ".") ? this.DOT_Y_POSITION : this.DEFAULT_Y_POSITION;
                    placeholder.colorMultiply.alpha = 1;
                }
            }
        }
    }

    onShowHelpPage(){
        this.menuPanel.disable();

        helpWindow.show();
    }

    onVolumeTweak(){
        //Toggle audio to mute/unmute
        pr.audioController.toggleMute();
        this.menuVolumeButton.setGraphicAsset(pr.audioController.isMuted ? nc.graphicAssets.panel_button_volume_disable_001: nc.graphicAssets.panel_button_volume_003);
    }

    onReturnToLobby(){
        this.menuPanel.disable();

        //Set game to return lobby
    }

    wait(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }

    async onPlayDashboardGoldFrameGlow(){
        const delayBeforeReplay = this.dashboardFrame.spriteSetter.duration * 300;
        this.dashboardFrame.spriteSetter.playOnce();
        await this.wait(delayBeforeReplay);
        this.onPlayDashboardGoldFrameGlow();
    }

    async onDirectionButtonWinGlow(){
        
    }
}
class GameIntro extends FlowState {
    constructor() {
        super();
        this.userPressedPlay = false;
        this.hasPlayedIntroAnimation = false;
        this.playButton = pr.gameLayout.descendantsByName.playButton;
        this.playPanel = pr.gameLayout.descendantsByName.PlayPanel; 
        this.bgPanel = pr.gameLayout.descendantsByName.BGPanel;
        this.claw = pr.gameLayout.descendantsByName.ClawConstruct;

        this.BG_MAX_X = ProjectSettings.BG_MAX_X;
        this.BG_MAX_Y = ProjectSettings.BG_MAX_Y;

        this.addElement(0, "startGameIntro");
        this.addPause(0.1, "waitForUserToPressedPlay"); 
    }

    startGameIntro() {
        if (this.playButton) {
            this.playButton.visible = true;
            this.playButton.buttonActive = true; 
            this.playButton.addReleaseCallback(this, "userPlayButtonPressed");
        }
    }

    async userPlayButtonPressed() {
        pr.audioController.playSFX("3_pop_up_appearance");

        if (this.playButton) {
            this.playButton.buttonActive = false;
            this.playButton.visible = false;
        }
        if (this.playPanel) this.playPanel.disable();

        // The backdrop flash belongs to the first entry only -- GameIdle re-arms
        // this same button for every later round.
        this.hasPlayedIntroAnimation = false;
        if (!this.hasPlayedIntroAnimation) {
            await this.runAnimationSequence();
            this.hasPlayedIntroAnimation = true;
        }

        if (this.claw) this.claw.enable();
        this.userPressedPlay = true;

        // There is no stake to choose: Start buys the ticket and the round
        // begins with its fixed allocation of picks -- unless a mid-round
        // ticket survived a disconnect (staged onto pendingResume during
        // bootstrap, see ProjectMain.js STEP 7), in which case resume it
        // instead of buying a new one.
        if (pr.setBetController?.pendingResume) {
            const { ticket, progress } = pr.setBetController.pendingResume;
            pr.setBetController.pendingResume = null;
            const resumed = await pr.setBetController.resumeRoundFromTicket(ticket, progress);
            if (!resumed) {
                // Saved progress couldn't be trusted -- settle the stale
                // ticket and fall back to a normal fresh round rather than
                // stranding the player on an unresumable one.
                await pr.wrapperManager._doSettleTicket().catch(() => {});
                pr.setBetController.startRound();
            }
        } else {
            pr.setBetController.startRound();
        }
    }

    async runAnimationSequence() {
        const duration = ProjectSettings.PANEL_SWOOP_DURATION_S;

        if (this.bgPanel) {
            this.bgPanel.enable();
            if (this.bgPanel?.materialMaster.fillColor.swoop) {
                this.bgPanel.materialMaster.fillColor.swoop.alpha(0, duration);
                await this.wait(duration * 1000);
                this.bgPanel.materialMaster.fillColor.swoop.alpha(1, duration);
                await this.wait(duration * 1000);
            }
            this.bgPanel.disable();
        }
    }

    wait(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }
    waitForUserToPressedPlay() { return this.userPressedPlay; }
}
class GameIdle extends FlowState {
    constructor() {
        super();
        this.addElement(0, "startIdle");
    }

    async startIdle() {
        await new Promise(r => setTimeout(r, ProjectSettings.IDLE_ENTRY_DELAY_MS));

        if (pr.prizeController) pr.prizeController.resetWinState();
        if (pr.setBetController) pr.setBetController.resetVariables();

        // Re-arm Start so the player can buy the next ticket. The release
        // callback registered by GameIntro is still attached to this button.
        const playButton = pr.gameLayout.descendantsByName.playButton;
        if (playButton) {
            playButton.visible = true;
            playButton.buttonActive = true;
        }
        const playPanel = pr.gameLayout.descendantsByName.PlayPanel;
        if (playPanel) playPanel.enable();
        const bgPanel = pr.gameLayout.descendantsByName.BGPanel;
        if (bgPanel) bgPanel.enable();
        if (pr.systemMessageController) pr.systemMessageController.showMessage(1);
    }
}
