class ClawMoving extends FlowState {
    constructor() {
        super();
        this.addElement(0, "onEnter");
    }

    async onEnter() {
        const controller = pr.setBetController;
        const claw = controller.claw;

        if (controller && claw) {
            const tName = controller.lastTimelineName;
            if (tName && claw.timelines && claw.timelines[tName]) {
                const targetTl = claw.timelines[tName];
                
                targetTl.stop();        
                targetTl.time = 0;      
                targetTl.influence = 1; 
                targetTl.loop = false; 
                
                if (typeof targetTl.playOnce === 'function') {
                    targetTl.playOnce();
                } else {
                    targetTl.play();
                }
            }
        }

        await new Promise(resolve => setTimeout(resolve, ProjectSettings.CLAW_IN_ANIM_DELAY_MS));
        nc.flows.MainGameFlow.ClawStopMoving.setToCurrentState();
    }
}
class ClawStopMoving extends FlowState {
    constructor() {
        super();
        this.addElement(0, "onEnter");
    }

    async onEnter() {
        const controller = pr.setBetController;
        
        if (controller) {
            controller.isMoving = false; 
            
            if (controller.currentSelections > 0) {
                controller.dirButtons.forEach(db => db.buttonActive = true);
                nc.flows.MainGameFlow.StartGame.setToCurrentState();
            } else {
                console.log("No moves left.");
            }
        }
    }
}
class PrizeWin extends FlowState {
    constructor() {
        super();
        this.addElement(0, "showWinPanel");
    }

    async showWinPanel() {
        if (pr.prizeController && pr.prizeController.isWinningState) {
            const typeId = pr.prizeController.winningType;
            const winAmount = Number(pr.setBetController?.currentTicketWinAmount) || 0;
            const totalBet = ProjectSettings.TOTAL_BET_CREDITS;
            // UK/Ontario: no celebratory audio/visual treatment for a return
            // that is less than or equal to the total amount wagered -- the win
            // amount itself still displays via displayTotalWin(), this only
            // gates the "you won" banner + SFX celebration. Only actually
            // applies in a jurisdiction configured to require it (see
            // ProjectSettings.WIN_CELEBRATION_GATED_JURISDICTIONS) -- NJ (the
            // only jurisdiction actually shipped today) has no such rule, so
            // every win celebrates there regardless of amount.
            const gateApplies = pr.wrapperManager?.requiresWinCelebrationGate?.() ?? false;
            if (typeId && (!gateApplies || winAmount > totalBet)) {
                pr.prizeController.showWinPanel(typeId);
            }
        }

        // Wait for the win panel to finish its entrance animation before
        // revealing the remaining moves so they don't compete for attention.
        await this.wait(ProjectSettings.MOVES_REVEAL_ENTRY_DELAY_MS);

        if (nc.flows.MainGameFlow.MovesRevealed) {
            nc.flows.MainGameFlow.MovesRevealed.setToCurrentState();
        }
    }

    wait(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}
class MovesRevealed extends FlowState {
    constructor() {
        super();
        this.addElement(0, "revealRemainingMoves");
    }

    async revealRemainingMoves() {
        const controller = pr.setBetController;
        if (!controller) return;

        const assetsSource = nc.graphicAssets || nc.assets || {};

        // The ghost reveal must come from the same 30-card pool the real
        // scenario was dealt from -- 18 BLANK, 3 each of UP/DOWN/LEFT/RIGHT
        // (see Tools/verify-clawfest-6-math.py, which verifies this exact
        // composition against the deployed config) -- minus the 6 cards the
        // ticket's own scenario already drew this round. A flat, uniform
        // pick across the 5 direction labels (previously used here) gives
        // ~20% blank instead of the correct ~60%, and doesn't reproduce the
        // per-tier probabilities the math relies on.
        const fullPool = [
            ...Array(18).fill("BLANK"),
            ...Array(3).fill("UP"),
            ...Array(3).fill("DOWN"),
            ...Array(3).fill("LEFT"),
            ...Array(3).fill("RIGHT")
        ];
        const remainingPool = fullPool.slice();
        const drawnMoves = Array.isArray(controller.currentScenarioMoves) ? controller.currentScenarioMoves : [];
        drawnMoves.forEach(move => {
            const idx = remainingPool.indexOf(move);
            if (idx !== -1) remainingPool.splice(idx, 1);
        });
        // Fisher-Yates shuffle so the remaining cards land on the unused
        // buttons in a random order, same as an unbiased deal would.
        for (let i = remainingPool.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [remainingPool[i], remainingPool[j]] = [remainingPool[j], remainingPool[i]];
        }
        let poolCursor = 0;

        for (let i = 0; i < controller.dirButtons.length; i++) {
            const btn = controller.dirButtons[i];
            if (!btn) continue;
            if (btn.isUsed) continue;

            const rawDir = poolCursor < remainingPool.length ? remainingPool[poolCursor++] : "BLANK";
            const dir = pr.wrapperManager.mapScenarioDirection(rawDir);

            // Apply the direction graphic to the button.
            const asset = assetsSource[`button_${dir}`];
            if (asset) {
                if (typeof btn.setGraphicAsset === "function") btn.setGraphicAsset(asset);
                else btn.texture = asset;
            }

            if (pr.audioController) pr.audioController.playSFX("18_button_reveal");

            btn.buttonActive = false;
            if (btn.colorMultiply) {
                if (btn.colorMultiply.swoop) {
                    btn.colorMultiply.swoop.alpha(
                        ProjectSettings.MOVES_REVEAL_GHOST_ALPHA,
                        ProjectSettings.MOVES_REVEAL_FADE_DURATION_S
                    );
                } else {
                    btn.colorMultiply.alpha = ProjectSettings.MOVES_REVEAL_GHOST_ALPHA;
                }
            }

            await this.wait(ProjectSettings.MOVES_REVEAL_STAGGER_MS);
        }

        // On the loss path there is no win panel, so show the "play again" prompt here.
        // On the win path, PrizeController.isWinningState is still true at this point.
        const isLoss = !pr.prizeController || !pr.prizeController.isWinningState;
        if (isLoss && pr.systemMessageController) {
            pr.systemMessageController.showMessage(16);
        }

        if (pr.dashboardController) pr.dashboardController.setDashboardButtonsActive(true);
        if (pr.setBetController) pr.setBetController.setMetaButtonActive(true);
    }

    wait(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}
/**
 * GameWrapperManager
 * Handles Fingenuity / Gromada GameWrapper integration for Clawfest (Fixed Odds)
 *
 * Architecture follows lucky5s pattern:
 *   init()          → load wrapper assets only
 *   setupFromRgs()  → instantiate wrapper with full game config from RGS
 *   refreshInitialState() → call getGame/refresh, parse stakes/modes
 *   finalizeBootstrap → handle unsettled ticket → gameReady
 */

class GameWrapperManager {
    constructor() {
        this.wrapper = null;
        this.wrapperBasePath = null;
        this.launchContext = null;
        this.state = "init";
        this.isWrapperEnabled = true;
        this.loadingScreenStartedAt = 0;
        this.loadingScreenMinMs = ProjectSettings.LOADING_SCREEN_MIN_MS;
        this._gwLoadingBrandTimer = null;
        this._isSpinTransactionActive = false;
        this._isHistoryReplayActive = false;
        this.stakes = [];
        this.currentStake = null;
        this.currentTicket = null;
        this.bottomBarScreenPadding = ProjectSettings.BOTTOM_BAR_SCREEN_PADDING;
        this._appliedCanvasBottomPaddingPx = -1;
        this.wrapperConfigPaths = [
            "./wrapper-config.json",
            "./ProjectCode/wrapper-config.json",
            "./Publishing/Builds/wrapper-config.json"
        ];
        this.wrapperConfigPath = this.wrapperConfigPaths[0];
        this.wrapperConfigOverrides = null;
        this.soundVolume = 1;
        this._wrapperEventsRegistered = false;
        this._wrapperEventsRegistrationScheduled = false;
        this._gameReadySent = false;
        this._isSyncingStake = false;

        this.lastAction = null;

        // See ProjectCode/LocalRgs.js -- set by setupLocalRgs() in init() when
        // LocalRgs.shouldEnable() opts in. null means "talk to the real RGS".
        this.localRgs = null;

        // Single game. Total bet is fixed at 6 credits per Math_Clawfest_V4;
        // the player varies denomination, not credit count.
        this.gameId = "clawfest-6";

        this.allowedOrigins = [
            window.location.origin,
            "https://launcher.example.com",
            "https://staging.launcher.example.com"
        ];

        this.defaultStakes = [6];
    }

    // -------------------------------------------------------
    // Asset loading
    // -------------------------------------------------------
    getWrapperBaseCandidates() {
        return [
            "./libs/gamewrapper",
            "../libs/gamewrapper",
            "./gamewrapper",
            "../gamewrapper",
            "../../gamewrapper",
            "./Publishing/Builds/gamewrapper",
            "../Publishing/Builds/gamewrapper"
        ];
    }

    loadExternalScriptOnce(src) {
        return new Promise((resolve, reject) => {
            const existing = document.querySelector(`script[data-gw-src="${src}"]`);
            if (existing) { resolve(); return; }
            const script = document.createElement("script");
            script.src = src;
            script.async = false;
            script.dataset.gwSrc = src;
            script.onload = () => resolve();
            script.onerror = () => reject(new Error(`Failed to load script: ${src}`));
            document.head.appendChild(script);
        });
    }

    async isValidWrapperScriptUrl(src) {
        try {
            const response = await fetch(src, { cache: "no-store" });
            if (!response.ok) return false;
            const body = await response.text();
            const sample = body.slice(0, 400);
            if (/^\s*</.test(sample)) return false;
            if (/^\s*Request\b/i.test(sample)) return false;
            return body.includes("GameWrapper");
        } catch (_err) {
            return false;
        }
    }

    ensureWrapperCss(basePath) {
        const href = `${basePath}/gamewrapper.css`;
        const existing = document.querySelector(`link[data-gw-href="${href}"]`);
        if (existing) return;
        const link = document.createElement("link");
        link.rel = "stylesheet";
        link.href = href;
        link.dataset.gwHref = href;
        document.head.appendChild(link);
    }

    detectLoadedWrapperBasePath() {
        const scriptTag = Array.from(document.scripts || []).find(s =>
            typeof s.src === "string" && /\/gamewrapper(\.min)?\.js(\?.*)?$/i.test(s.src)
        );
        if (!scriptTag || !scriptTag.src) return null;
        return scriptTag.src.replace(/\/gamewrapper(\.min)?\.js(\?.*)?$/i, "");
    }

    async ensureWrapperAssetsLoaded() {
        const gw = window.GameWrapper;
        if (gw && typeof gw.GameWrapper === "function") {
            const detectedBase = this.detectLoadedWrapperBasePath();
            const basePath = detectedBase || this.getWrapperBaseCandidates()[0];
            this.ensureWrapperCss(basePath);
            return basePath;
        }

        for (const basePath of this.getWrapperBaseCandidates()) {
            try {
                const scriptUrl = `${basePath}/gamewrapper.min.js`;
                const isValid = await this.isValidWrapperScriptUrl(scriptUrl);
                if (!isValid) continue;
                this.ensureWrapperCss(basePath);
                await this.loadExternalScriptOnce(scriptUrl);
                if (window.GameWrapper && typeof window.GameWrapper.GameWrapper === "function") {
                    return basePath;
                }
            } catch (_err) {
                // try next candidate
            }
        }

        throw new Error("[GW] gamewrapper.min.js not found. Check libs/gamewrapper/.");
    }

    patchWrapperCompatibility() {
        const GWClass = window.GameWrapper?.GameWrapper;
        if (!GWClass || GWClass.__cfCompatibilityPatched) return;

        const originalGetLanguageMap = GWClass.prototype.getLanguageMap;
        if (typeof originalGetLanguageMap === "function") {
            GWClass.prototype.getLanguageMap = async function (...args) {
                try {
                    return await originalGetLanguageMap.apply(this, args);
                } catch (_err) {
                    console.warn("[GW] language-config.json missing/invalid, continuing without language map");
                    return undefined;
                }
            };
        }

        GWClass.__cfCompatibilityPatched = true;
    }

    // -------------------------------------------------------
    // STEP 1: Initialize wrapper (load assets only — no instantiation)
    // -------------------------------------------------------
    async init() {
        this.loadingScreenStartedAt = performance.now();

        let isPublished = true;
        ;

        if (window.nc && nc.projectConfiguration) {
            if (nc.projectConfiguration.publishTimestamp === "devMode") {
                isPublished = false;
            } else if (typeof nc.projectConfiguration.isProjectPublished === "boolean") {
                isPublished = nc.projectConfiguration.isProjectPublished;
            }
        }

        // LocalRgs -- lets the game run with zero network calls to the real
        // RGS, for offline dev/QA. Only takes effect when explicitly
        // requested (LocalRgs.shouldEnable() checks
        // ProjectSettings.LOCAL_RGS_ENABLED_BY_DEFAULT, ?localrgs=1/?local-rgs=1,
        // and a localStorage flag). By default this also skips the real
        // GameWrapper library entirely (isPublished forced false below, same
        // as the existing editor/unpublished path) -- RGS calls are served
        // by direct in-process calls into LocalRgs from callRgsMethod(), no
        // wrapper instance and no XHR involved at all. Pass
        // ?localrgs-wrapper=1 / ProjectSettings.LOCAL_RGS_LOAD_WRAPPER to
        // opt into loading the real wrapper anyway, with its RGS calls
        // served via a transport intercept instead -- see
        // ProjectCode/LocalRgs.js for both modes.
        //
        // "LocalDev" IS a real, project-registered conditional code tag
        // (see conditionalCodeTagDefinitions / configurations.LocalDev in
        // ProjectSettings.json at the repo root, not ProjectCode/ProjectSettings.js)
        // -- distinct from the built-in *___published/*___unpublished pair
        // above. Every Publishing/Builds/*_LocalDev output (all of them, so
        // far) explicitly includes "LocalDev" in conditionalCodeTagsIncluded,
        // so this block ships in those; a WebPublish/EgmPublish configuration
        // that does NOT list "LocalDev" there would have it stripped. (An
        // earlier version of this comment claimed the tag was unrecognised
        // and never stripped -- that was wrong; corrected 3 Sep 2026.)
        ;
        if (LocalRgs.shouldEnable()) {
            this.localRgs = new LocalRgs(this);
            const localRgsReady = await this.localRgs.enable();
            if (localRgsReady) {
                // Default: standalone -- no GameWrapper library loaded at all,
                // RGS calls served by direct in-process calls into LocalRgs
                // (see callRgsMethod() below). Opt into loading the real
                // wrapper instead (RGS calls served via transport intercept)
                // with ?localrgs-wrapper=1 / ProjectSettings.LOCAL_RGS_LOAD_WRAPPER.
                isPublished = LocalRgs.shouldLoadWrapper();
            }
        }
        ;

        if (!isPublished) {
            this.isWrapperEnabled = false;
            this.state = "active";
            console.log(this.localRgs?.enabled
                ? "[GW] LocalRgs standalone mode -- no GameWrapper library loaded, RGS calls served locally"
                : "[GW] Skipping wrapper init in editor/unpublished runtime");
            return;
        }

        const wrapperBasePath = await this.ensureWrapperAssetsLoaded();
        this.wrapperBasePath = wrapperBasePath;

        console.log("[GW] Wrapper assets loaded at:", wrapperBasePath);

        if (typeof window.GameWrapper?.GameWrapper !== "function") {
            throw new Error("[GW] GameWrapper class not available after script load.");
        }

        this.patchWrapperCompatibility();
        await this.loadWrapperConfigFromJson();

        this.setLoadingProgress(0.05);
    }

    // -------------------------------------------------------
    // Config loading
    // -------------------------------------------------------
    async loadWrapperConfigFromJson() {
        if (!this.isWrapperEnabled) return null;

        const paths = Array.isArray(this.wrapperConfigPaths) && this.wrapperConfigPaths.length > 0
            ? this.wrapperConfigPaths
            : [this.wrapperConfigPath];

        for (const path of paths) {
            try {
                const response = await fetch(path, { cache: "no-store" });
                if (!response.ok) continue;
                const parsed = await response.json();
                if (!parsed || typeof parsed !== "object") continue;
                this.wrapperConfigPath = path;
                this.wrapperConfigOverrides = parsed;
                console.log("[GW] Loaded wrapper config JSON:", this.wrapperConfigPath);
                return parsed;
            } catch (_err) {
                // try next
            }
        }

        console.warn("[GW] wrapper-config.json not found. Using in-code defaults.");
        this.wrapperConfigOverrides = null;
        return null;
    }

    mergeWrapperConfig(defaultConfig) {
        const overrides = this.wrapperConfigOverrides;
        if (!overrides || typeof overrides !== "object") return defaultConfig;

        const merged = {
            ...defaultConfig,
            ...overrides,
            ui: {
                ...(defaultConfig.ui || {}),
                ...(overrides.ui || {}),
                splash: {
                    ...(defaultConfig.ui?.splash || {}),
                    ...(overrides.ui?.splash || {})
                },
                bottomBar: {
                    ...(defaultConfig.ui?.bottomBar || {}),
                    ...(overrides.ui?.bottomBar || {})
                },
                topBar: (typeof overrides.ui?.topBar === "object" && typeof defaultConfig.ui?.topBar === "object")
                    ? { ...(defaultConfig.ui?.topBar || {}), ...(overrides.ui?.topBar || {}) }
                    : (overrides.ui?.topBar ?? defaultConfig.ui?.topBar)
            },
            gameConfig: {
                ...(defaultConfig.gameConfig || {}),
                ...(overrides.gameConfig || {})
            }
        };

        if (Object.prototype.hasOwnProperty.call(overrides, "postMessage")) {
            merged.postMessage = overrides.postMessage;
        }

        return merged;
    }

    // -------------------------------------------------------
    // Payload parsing — adapt lucky5s pattern for fixed-odds
    // -------------------------------------------------------
    parseRefreshPayload(refreshData) {
        if (!refreshData || typeof refreshData !== "object") {
            throw new Error("Invalid RGS refresh/getGame response.");
        }

        // Fixed-odds: getGame returns game config directly
        const remoteGameConfig = refreshData.gameConfig
            || refreshData.config?.gameConfig
            || refreshData.game
            || refreshData;

        if (!remoteGameConfig || typeof remoteGameConfig !== "object") {
            throw new Error("RGS refresh/getGame response does not contain gameConfig.");
        }

        const gameId = remoteGameConfig.gameId || refreshData.gameId || "clawfest";
        const gameType = "fixed-odds";
        const gameEngine = "fixed-odds";

        // Extract stake list (ticketPrice for fixed-odds)ß
        const rawStakeList = refreshData.stakes
            || refreshData.ticketPrice
            || remoteGameConfig.stakes
            || remoteGameConfig.ticketPrice
            || [];

        let stakes = Array.isArray(rawStakeList) ? rawStakeList : [];
        stakes = stakes
            .map(v => Number(v))
            .filter(v => Number.isFinite(v) && v > 0);

        if (stakes.length === 0) {
            const singleStakeCandidate = Number(
                refreshData.defaultStake
                ?? refreshData.stake
                ?? refreshData.currentStake
                ?? remoteGameConfig.defaultStake
                ?? remoteGameConfig.stake
            );
            if (Number.isFinite(singleStakeCandidate) && singleStakeCandidate > 0) {
                stakes = [singleStakeCandidate];
            }
        }

        if (stakes.length === 0) {
            stakes = this.defaultStakes.slice();
            console.warn("[GW] RGS response missing stake list; defaulting to", stakes);
        }

        const defaultStake = refreshData.defaultStake ?? refreshData.stake ?? stakes[0];

        const launchContext = {
            raw: refreshData,
            mode: "normal",
            gameId,
            gameType,
            gameEngine,
            defaultStake,
            stakes,
            gameConfig: {
                ...remoteGameConfig,
                gameId,
                gameType,
                gameEngine
            }
        };

        this.launchContext = launchContext;
        console.log("[GW] launchContext:", this.launchContext);
        return launchContext;
    }

    buildWrapperConfig(launchContext) {
        const remoteGameConfig = launchContext.gameConfig;
        const gameId = launchContext.gameId;
        const gameType = launchContext.gameType;
        const gameEngine = launchContext.gameEngine;
        const basePath = this.wrapperBasePath || "./libs/gamewrapper";
        // one level up from the wrapper folder, where the game's own copies live
        const gameRoot = basePath.replace(/\/gamewrapper\/?$/, "") || ".";

        const sanitizedTicketPrice = Array.isArray(remoteGameConfig.ticketPrice)
            ? remoteGameConfig.ticketPrice.map(v => Number(v)).filter(v => Number.isFinite(v) && v > 0)
            : launchContext.stakes;

        const normalizedGameConfig = {
            ...remoteGameConfig,
            gameId,
            gameType,
            gameEngine,
            ticketPrice: sanitizedTicketPrice.length > 0 ? sanitizedTicketPrice : launchContext.stakes
        };

        const canvas = document.querySelector("canvas");

        // Extract JWT and RPC URL from launch context or URL
        const jwt = launchContext?.raw?.jwt 
            || new URLSearchParams(window.location.search).get('jwt')
            || this.extractJwtFromCookie();
        
        // RPC URL can be overridden by launch context or URL params. When
        // LocalRgs is active it always wins -- see ProjectCode/LocalRgs.js.
        const urlParams = new URLSearchParams(window.location.search);
        const rpcUrl = this.localRgs?.enabled
            ? LocalRgs.RPC_URL
            : (launchContext?.raw?.rpcUrl
                || urlParams.get('rpcUrl')
                || urlParams.get('rpc-url')
                || "https://gromada-dev.finrings.com/api/rpc");

        const defaultWrapperConfig = {
            gameId,
            gameType,
            gameEngine,
            content: canvas || "#game_canvas",
            container: document.body,
            params: {
                jwt,
                nyxGameId: urlParams.get('nyxGameId') || gameId,
                currency: urlParams.get('currency') || "USD",
                isPlayForFun: urlParams.get('isPlayForFun') === 'true' || urlParams.get('demo') === 'true',
                jurisdiction: this.getJurisdictionCode() || undefined
            },
            rpcUrl,
            ui: {
                topBar: false,
                splash: { logo: true, progressBar: true },
                bottomBar: {
                    btnMenu: false,
                    btnLobby: true,
                    btnHelp: false,
                    btnSound: true,
                    btnAutoplay: false,
                    lblBalance: true,
                    lblBet: true,
                    lblWinAmount: true,
                    lblGameMode: true
                }
            },
            ticketPrice: normalizedGameConfig.ticketPrice,
            gameConfig: normalizedGameConfig,
            playerConfig: {
                playerId: "demo",
                balance: launchContext?.raw?.balance ?? 1000,
                currency: "USD"
            },
            postMessage: {
                allowedEvents: [
                    "betStops",
                    "volume",
                    "updatePlayer",
                    "gameReady",
                    "gameStart",
                    "gameEnd",
                    "bonusStart",
                    "bonusEnd",
                    "outOfCoins",
                    "error"
                ],
                boolean: { true: "true", false: "false" }
            },
            langPath: `${basePath}/lang`,
            // jurisdiction and currency data are game-owned: keep them outside
            // libs/gamewrapper, which is replaced wholesale on every wrapper drop.
            jurisdictionPath: `${gameRoot}/jurisdiction`,
            currencyData: `${gameRoot}/currency.json`
        };

        return this.mergeWrapperConfig(defaultWrapperConfig);
    }

    // -------------------------------------------------------
    // STEP 2: Setup wrapper from RGS response (instantiate wrapper)
    // -------------------------------------------------------
    
    /**
     * Build a minimal launch context from local config before RGS call.
     * This allows wrapper instantiation before getGame/refresh.
     */
    buildLaunchContextFromConfig() {
        const gameId = this.wrapperConfigOverrides?.gameId || this.gameId;

        const stakes = this.wrapperConfigOverrides?.stakes
            || this.wrapperConfigOverrides?.gameConfig?.stakes
            || this.wrapperConfigOverrides?.gameConfig?.ticketPrice
            || this.defaultStakes.slice();

        const defaultStake = this.wrapperConfigOverrides?.defaultStake
            || this.wrapperConfigOverrides?.gameConfig?.defaultStake
            || stakes[0];

        const remoteGameConfig = this.wrapperConfigOverrides?.gameConfig || {};

        // Extract JWT from URL params
        const urlParams = new URLSearchParams(window.location.search);
        const jwt = urlParams.get('jwt') || this.extractJwtFromCookie();

        const launchContext = {
            raw: {
                ...this.wrapperConfigOverrides,
                jwt,
                balance: this.wrapperConfigOverrides?.initialBalance ?? 1000
            },
            mode: "normal",
            gameId,
            gameType: "fixed-odds",
            gameEngine: "fixed-odds",
            defaultStake,
            stakes,
            gameConfig: {
                ...remoteGameConfig,
                gameId,
                gameType: "fixed-odds",
                gameEngine: "fixed-odds"
            }
        };

        this.launchContext = launchContext;
        console.log("[GW] launchContext from config:", this.launchContext);
        return launchContext;
    }

    extractJwtFromCookie() {
        const match = document.cookie.match(/(?:^|;\s*)jwt\s*=\s*([^;]*)/);
        return match ? match[1] : null;
    }

    setupFromRgs(refreshData) {
        if (!this.isWrapperEnabled) return false;
        if (this.wrapper) return true;

        // If refreshData is null/empty, use existing launchContext from buildLaunchContextFromConfig
        const launchContext = refreshData?.raw 
            ? refreshData 
            : (refreshData ? this.parseRefreshPayload(refreshData) : this.launchContext);
        
        if (!launchContext) {
            console.error("[GW] Cannot setup wrapper: no launch context available.");
            return false;
        }
        
        const wrapperConfig = this.buildWrapperConfig(launchContext);
        console.log("[GW] Wrapper config RPC URL:", wrapperConfig.rpcUrl);
        console.log("[GW] Wrapper config JWT present:", !!wrapperConfig.params?.jwt);
        
        this.wrapper = new window.GameWrapper.GameWrapper(wrapperConfig);
        console.log("[GW] GameWrapper instantiated via setupFromRgs");

        this.ensureWrapperUiOnTop();
        this.ensureBottomBarBelowCanvas();
        this.ensureBottomBarControlsVisible();
        this.ensureLoadingBrandVisible();
        this.setLoadingProgress(0.05);
        this.registerEvents();
        this.registerPostMessage();
        return true;
    }

    // -------------------------------------------------------
    // STEP 3: Refresh initial state (getGame)
    // -------------------------------------------------------
    async refreshInitialState() {
        console.log("[GW] Checking RGS methods...");
        console.log("[GW] this.wrapper:", this.wrapper);
        console.log("[GW] this.wrapper?.rgs:", this.wrapper?.rgs);
        console.log("[GW] this.wrapper?.rgs?.initGame:", typeof this.wrapper?.rgs?.initGame);
        console.log("[GW] this.wrapper?.rgs?.getGame:", typeof this.wrapper?.rgs?.getGame);
        console.log("[GW] this.wrapper?.rgs?.refresh:", typeof this.wrapper?.rgs?.refresh);
        
        // Single game: getGame() (or refresh()) is available directly on the
        // common rgs adapter. sendCustomRequest('GetGame') is the last resort.
        const hasGetGame  = typeof this.wrapper?.rgs?.getGame  === "function";
        const hasRefresh  = typeof this.wrapper?.rgs?.refresh  === "function";

        if (!hasGetGame && !hasRefresh) {
            console.warn("[GW] No getGame or refresh method available on RGS adapter!");
            console.warn("[GW] Available RGS methods:", Object.keys(this.wrapper?.rgs || {}));
            return {
                response: null,
                mode: "normal",
                stakes: this.stakes.slice(),
                defaultStake: this.currentStake || this.stakes[0],
                nextAction: "",
                hasUnfinishedGame: false,
                launchContext: this.launchContext
            };
        }

        if (this.wrapper?.ready) {
            await this.wrapper.ready;
        }

        let response;

        if (hasGetGame) {
            console.log("[GW] Calling getGame() on common rgs interface...");
            response = await this.callRgsMethod("getGame");
        } else if (hasRefresh) {
            console.log("[GW] Calling refresh()...");
            response = await this.callRgsMethod("refresh");
        } else {
            // Fixed-odds fallback: use sendCustomRequest
            console.log("[GW] Falling back to sendCustomRequest('GetGame')...");
            response = await this.callRgsMethod("sendCustomRequest", [
                "GameService",
                "GetGame",
                [this.wrapper?.rgs?.gameId || this.launchContext?.gameId || this.gameId]
            ]);
        }
        
        console.log("[GW] getGame/refresh response:", response);

        if (response && typeof response === "object") {
            const hasConfigPayload = !!(
                response.gameConfig
                || response.config?.gameConfig
                || (Array.isArray(response.ticketPrice) || response.gameEngine)
            );

            if (hasConfigPayload) {
                try {
                    this.parseRefreshPayload(response);
                } catch (parseError) {
                    console.warn("[GW] Could not parse refresh payload:", parseError);
                }
            }
        }

        const stakes = (Array.isArray(response?.stakes) ? response.stakes : [])
            .map(v => Number(v))
            .filter(v => Number.isFinite(v) && v > 0);

        if (stakes.length === 0 && this.launchContext?.stakes) {
            stakes.push(...this.launchContext.stakes);
        }

        if (stakes.length > 0 && this.launchContext) {
            this.launchContext.stakes = stakes.slice();
        }

        const defaultStakeRaw = response?.defaultStake
            ?? response?.stake
            ?? this.launchContext?.defaultStake
            ?? stakes[0];
        const defaultStake = Number(defaultStakeRaw);
        if (Number.isFinite(defaultStake) && defaultStake > 0 && this.launchContext) {
            this.launchContext.defaultStake = defaultStake;
        }

        const nextAction = this.getNextAction(response);
        const hasUnfinishedGame = this.hasUnfinishedRound(response);

        return {
            response,
            mode: "normal",
            stakes: stakes.length > 0 ? stakes : this.stakes.slice(),
            defaultStake: Number.isFinite(defaultStake) && defaultStake > 0
                ? defaultStake
                : (this.currentStake || this.stakes[0]),
            nextAction,
            hasUnfinishedGame,
            launchContext: this.launchContext
        };
    }

    getNextAction(payload) {
        const rawAction = payload?.game?.nextAction
            ?? payload?.nextAction
            ?? payload?.game?.action
            ?? "";
        return String(rawAction || "").toLowerCase();
    }

    hasUnfinishedRound(payload) {
        const nextAction = this.getNextAction(payload);
        return nextAction.length > 0 && nextAction !== "purchaseTicket";
    }

    // -------------------------------------------------------
    // Stake management
    // -------------------------------------------------------
    setStakes(stakes) {
        const normalized = (Array.isArray(stakes) ? stakes : [])
            .map(v => Number(v))
            .filter(v => Number.isFinite(v) && v > 0);

        this.stakes = normalized.length > 0 ? normalized : this.defaultStakes.slice();
        console.log("[GW] Stakes set:", this.stakes);
    }

    setDefaultStake(stake) {
        this.syncStakeFromBet(stake, { propagateToWrapper: false, updateDashboard: false, source: "default-stake" });
    }

    syncStakeFromBet(betAmount, options = {}) {
        const {
            propagateToWrapper = true,
            updateDashboard = true,
            source = "unknown"
        } = options;

        const numericBet = Number(betAmount);
        if (!Number.isFinite(numericBet) || numericBet <= 0) return null;

        let resolvedStake = numericBet;
        if (Array.isArray(this.stakes) && this.stakes.length > 0) {
            const numericStakes = this.stakes.map(v => Number(v)).filter(v => Number.isFinite(v) && v > 0);
            if (numericStakes.length > 0) {
                const exactMatch = numericStakes.find(v => v === numericBet);
                if (typeof exactMatch === "number") {
                    resolvedStake = exactMatch;
                } else {
                    resolvedStake = numericStakes.reduce((closest, current) => {
                        return Math.abs(current - numericBet) < Math.abs(closest - numericBet) ? current : closest;
                    }, numericStakes[0]);
                }
            }
        }

        this.currentStake = resolvedStake;

        // Keep legacy currentBet in sync for clawfest game code
        this.currentBet = resolvedStake;

        if (updateDashboard && pr?.dashboardController) {
            this.updateBetDisplay(resolvedStake);
        }

        if (propagateToWrapper && this.wrapper?.setBet && !this._isSyncingStake) {
            try {
                this._isSyncingStake = true;
                this.wrapper.setBet(resolvedStake);
            } catch (e) {
                console.warn("[GW] wrapper.setBet failed:", e);
            } finally {
                this._isSyncingStake = false;
            }
        }

        return resolvedStake;
    }

    // -------------------------------------------------------
    // Event registration
    // -------------------------------------------------------
    registerEvents() {
        if (this._wrapperEventsRegistered) return;

        if (!this.wrapper?.ui) {
            if (!this._wrapperEventsRegistrationScheduled) {
                this._wrapperEventsRegistrationScheduled = true;
                Promise.resolve(this.wrapper?.initialized || this.wrapper?.ready)
                    .then(() => {
                        this._wrapperEventsRegistrationScheduled = false;
                        this.registerEvents();
                    })
                    .catch(() => { this._wrapperEventsRegistrationScheduled = false; });
            }
            return;
        }

        console.log("[GW] Registering wrapper events");

        const w = this.wrapper;
        const ui = this.wrapper?.ui;
        const on = (emitter, evt, handler) => {
            if (emitter && typeof emitter.on === "function") emitter.on(evt, handler);
        };

        on(w, "game-resume", () => this.onResume());
        on(w, "game-pause", () => this.onPause());
        on(ui, "game-resume", () => this.onResume());
        on(ui, "game-pause", () => this.onPause());

        on(w, "set-stake-limits", e => this.onStakeLimits(this.extractEventDetail(e)));
        on(w, "stake-change", e => this.onStakeChange(this.extractEventDetail(e)));

        on(ui, "sound-mute", () => {
            nc.sounds.setMute(true);
            if (pr.audioController) pr.audioController.mute();
        });
        on(ui, "sound-unmute", () => {
            nc.sounds.setMute(false);
            if (pr.audioController) pr.audioController.unmute();
        });
        on(ui, "sound-toggle", () => {
            const nowMuted = nc?.sounds?.isMuted ?? false;
            nc.sounds.setMute(!nowMuted);
            if (pr.audioController) {
                nowMuted ? pr.audioController.unmute() : pr.audioController.mute();
            }
        });
        on(ui, "sound-set-volume", e => this.applySoundVolume(this.extractEventDetail(e)));
        on(w, "sound-set-volume", e => this.applySoundVolume(this.extractEventDetail(e)));

        on(w, "error", e => this.onError(this.extractEventDetail(e)));
        on(w, "connection-lost", () => this.onConnectionLost());
        on(w, "connection-restored", () => this.onConnectionRestored());

        // account-data-received fires when the GameWrapper gets balance data from RGS,
        // including during recovery after an initGame() failure in multi-game mode.
        on(w, "account-data-received", e => {
            const data = this.extractEventDetail(e);
            const balance = Number(data?.balance);
            if (Number.isFinite(balance)) {
                console.log("[GW] account-data-received: balance =", balance);
                this.updateBalanceDisplay(balance);
            }
        });

        this._wrapperEventsRegistered = true;
        console.log("[GW] Events registered");
    }

    onStakeLimits(data) {
        console.log("[GW] set-stake-limits", data);
        const stakes = data?.stakes || data?.ticketPrice;
        if (Array.isArray(stakes) && stakes.length > 0) {
            this.setStakes(stakes);
        }

        // Keep current bet aligned
        if (typeof this.currentBet === "number") {
            this.syncStakeFromBet(this.currentBet, {
                propagateToWrapper: false,
                updateDashboard: true,
                source: "set-stake-limits"
            });
        }
    }

    onStakeChange(data) {
        if (this._isSpinTransactionActive) return;

        this.lastAction = { type: "STAKE_CHANGE", stake: data?.stake };
        this.syncStakeFromBet(data?.stake, {
            propagateToWrapper: false,
            updateDashboard: true,
            source: "wrapper-stake-change"
        });
    }

    // -------------------------------------------------------
    // Fixed Odds RGS API — purchase/settle ticket
    // -------------------------------------------------------

    /**
     * Purchase a ticket from the RGS.
     * Returns the ticket object containing the scenario for claw movement.
     */
    async purchaseTicket(bet) {
        if (!this.isWrapperEnabled && !this.localRgs?.enabled) {
            return this._getMockTicket(bet);
        }

        this._isSpinTransactionActive = true;
        try {
            const betAmount = bet || this.currentStake || this.currentBet;
            const ticket = await this.callRgsMethod("purchaseTicket", [betAmount]);
            this.currentTicket = ticket;
            return ticket;
        } finally {
            this._isSpinTransactionActive = false;
        }
    }

    /**
     * Settle the current ticket after the game round is complete.
     */
    async settleTicket() {
        if (!this.isWrapperEnabled && !this.localRgs?.enabled) {
            // Dev mode: simulate balance update after win
            if (pr?.setBetController?.currentTicketWinAmount > 0) {
                const dc = pr?.dashboardController;
                if (dc) {
                    const bal = parseFloat(dc.meters.balance.value.replace(/[^0-9.-]+/g, "")) || 0;
                    const win = pr.setBetController.currentTicketWinAmount;
                    this.updateBalanceDisplay(bal + win);
                    this.updateWinDisplay(win);
                }
            }
            this.currentTicket = null;
            return null;
        }

        return this._doSettleTicket();
    }

    async _doSettleTicket() {
        if (!this.currentTicket) return null;
        try {
            const result = await this.callRgsMethod("settleTicket");
            this.currentTicket = null;
            return result;
        } catch (err) {
            console.warn("[GW] settleTicket failed:", err);
            this.currentTicket = null;
            return null;
        }
    }

    // -------------------------------------------------------
    // Mid-round resume -- setTicketData() / getTicketData()
    // -------------------------------------------------------

    /**
     * Best-effort persistence of in-round progress via the RGS's native
     * setTicketData(), so a disconnect mid-round can resume the actual
     * animation instead of only settling straight to the final result
     * (NJ/Pennsylvania/Michigan/UK/Malta all ask for the former). This must
     * never block or fail gameplay -- errors are swallowed, not surfaced.
     */
    async saveTicketProgress(progress) {
        if ((!this.isWrapperEnabled && !this.localRgs?.enabled) || !this.currentTicket) return;
        try {
            await this.callRgsMethod("setTicketData", [progress]);
        } catch (err) {
            console.warn("[GW] setTicketData failed (non-fatal):", err);
        }
    }

    /**
     * Best-effort read-back of saveTicketProgress()'s data for a given
     * ticket (used during unsettled-ticket recovery, before the ticket has
     * been assigned as this.currentTicket). Returns null on any failure or
     * if nothing was ever saved for it -- callers must treat that the same
     * as "no saved progress" and fall back to settling immediately.
     */
    async loadTicketProgress(ticketId) {
        if (!this.isWrapperEnabled && !this.localRgs?.enabled) return null;
        try {
            const raw = await this.callRgsMethod("getTicketData", ticketId ? [ticketId] : []);
            if (!raw) return null;
            return typeof raw === "string" ? JSON.parse(raw) : raw;
        } catch (err) {
            console.warn("[GW] getTicketData failed (non-fatal):", err);
            return null;
        }
    }

    /**
     * Refresh balance from RGS and update the dashboard.
     */
    async syncBalance() {
        if (!this.isWrapperEnabled && !this.localRgs?.enabled) return;
        try {
            const account = await this.callRgsMethod("getAccount");
            const balance = Number(account?.balance) || 0;
            this.updateBalanceDisplay(balance);
            return balance;
        } catch (err) {
            console.warn("[GW] getAccount (sync) failed:", err);
            return null;
        }
    }

    // -------------------------------------------------------
    // Scenario parsing (fixed-odds specific)
    // -------------------------------------------------------
    parseTicketScenario(ticket) {
        if (!ticket) return null;
        const scenarioStr = ticket.prizes?.[0]?.scenario || ticket.scenario;
        if (!scenarioStr || typeof scenarioStr !== "string") return null;
        try {
            return JSON.parse(scenarioStr);
        } catch (e) {
            console.warn("[GW] Failed to parse scenario JSON:", e);
            return null;
        }
    }

    mapScenarioDirection(scenarioDir) {
        const map = { DOWN: "forward", UP: "backward", LEFT: "left", RIGHT: "right", BLANK: "blank" };
        return map[scenarioDir] || "forward";
    }

    scenarioPosToGridIndices(relX, relY) {
        return [
            Math.max(0, Math.min(6, 3 + relX)),
            Math.max(0, Math.min(6, 3 + relY))
        ];
    }

    _getMockTicket(bet) {
        // Dev/editor-only fallback for when there is no live RGS connection.
        // Deals from the same 30-card pool the real scenario uses (18 BLANK,
        // 3 each of UP/DOWN/LEFT/RIGHT -- see Tools/verify-clawfest-6-math.py,
        // which verifies this exact composition against the deployed config)
        // instead of an even 4-way pick with no BLANK at all, and pays out
        // from the real per-tier amounts in clawfest-6.json's "prize" array
        // (levels 1-6 map onto Manhattan tiers 1-6 by construction -- there
        // are exactly six of each; levels 7-16 are the ten equal-probability
        // Mystery Grab sub-prizes, awarded on landing at center per the
        // verified 12.5%-conditional trigger rate) instead of a made-up
        // 150/70/11/7/2 table with no top prize. These numbers are hand-
        // copied from the deployed config since this path never talks to
        // the RGS to fetch it live -- keep them in sync if clawfest-6.json's
        // prize table ever changes.
        const GRID_PRIZES = [0, 1, 5, 11, 70, 150, 7500]; // index = Manhattan tier (0-6)
        const MYSTERY_PRIZES = [30, 36, 42, 48, 54, 60, 66, 72, 78, 84]; // levels 7-16
        const MYSTERY_TRIGGER_PROB = 0.125; // conditional on landing at center

        const pool = [
            ...Array(18).fill("BLANK"),
            ...Array(3).fill("UP"),
            ...Array(3).fill("DOWN"),
            ...Array(3).fill("LEFT"),
            ...Array(3).fill("RIGHT")
        ];
        for (let i = pool.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [pool[i], pool[j]] = [pool[j], pool[i]];
        }
        const moves = pool.slice(0, 6);

        const positions = [];
        let x = 0, y = 0;
        moves.forEach(dir => {
            if (dir === "DOWN")       y = Math.min(3, y + 1);
            else if (dir === "UP")    y = Math.max(-3, y - 1);
            else if (dir === "RIGHT") x = Math.min(3, x + 1);
            else if (dir === "LEFT")  x = Math.max(-3, x - 1);
            positions.push([x, y]);
        });

        const tier = Math.abs(x) + Math.abs(y);
        let winAmount = 0;
        let prizeLevel = 0;
        if (tier === 0) {
            if (Math.random() < MYSTERY_TRIGGER_PROB) {
                const mysteryIndex = Math.floor(Math.random() * MYSTERY_PRIZES.length);
                winAmount = MYSTERY_PRIZES[mysteryIndex];
                prizeLevel = 7 + mysteryIndex;
            }
        } else {
            winAmount = GRID_PRIZES[tier] || 0;
            prizeLevel = tier;
        }

        const scenario = JSON.stringify({ s: moves, p: positions });
        return {
            ticketId: "mock-" + Date.now(),
            ticketPrice: bet,
            winAmount,
            prizes: [{ level: prizeLevel, winAmount, scenario }],
            prize: { level: prizeLevel, winAmount }
        };
    }

    // -------------------------------------------------------
    // RGS call infrastructure
    // -------------------------------------------------------
    async callRgsMethod(methodName, args = []) {
        console.log(`[GW] callRgsMethod: ${methodName}`, args);

        if (!this.wrapper?.rgs) {
            // Standalone LocalRgs (no GameWrapper instantiated) -- call the
            // matching method on LocalRgs directly instead of the real
            // adapter. Same method names/argument order as a real Rgs
            // adapter, so every existing call site works unmodified.
            if (this.localRgs?.enabled && typeof this.localRgs[methodName] === "function") {
                const result = await this.localRgs[methodName].apply(this.localRgs, Array.isArray(args) ? args : []);
                console.log(`[GW] LocalRgs (direct) ${methodName} returned:`, result);
                return result;
            }
            throw new Error(`[GW] RGS adapter unavailable for method: ${methodName}`);
        }
        const fn = this.wrapper.rgs[methodName];
        if (typeof fn !== "function") {
            throw new Error(`[GW] RGS method '${methodName}' is unavailable.`);
        }

        const canProceed = await this.waitForWrapperActiveState(`rgs.${methodName}`);
        if (!canProceed) {
            const err = new Error("requestBlocked");
            err.code = "requestBlocked";
            throw err;
        }

        console.log(`[GW] Invoking RGS method: ${methodName} with args:`, args);
        const result = await fn.apply(this.wrapper.rgs, Array.isArray(args) ? args : []);
        console.log(`[GW] RGS method ${methodName} returned:`, result);
        return result;
    }

    async waitForWrapperActiveState(label = "rgs-call", timeoutMs = ProjectSettings.WRAPPER_ACTIVE_TIMEOUT_MS) {
        if (!this.isWrapperEnabled || !this.wrapper) return true;

        const lState = String(this.state || "").toLowerCase();
        if (lState === "init" || lState === "loading") return true;

        const startedAt = Date.now();
        while ((Date.now() - startedAt) < timeoutMs) {
            const wState = String(this.wrapper?.state || "").toLowerCase();
            const isActive = wState === "active" || (!wState && lState === "active");
            if (isActive) return true;
            if (wState === "error" || lState === "error") {
                console.warn(`[GW] Aborting ${label}: wrapper in error state`);
                return false;
            }
            await new Promise(r => setTimeout(r, ProjectSettings.WRAPPER_ACTIVE_POLL_MS));
        }
        console.warn(`[GW] Timed out waiting for active state (${label})`);
        return false;
    }

    canCallRgs() {
        if (!this.isWrapperEnabled) return true;
        if (this._isHistoryReplayActive) return false;
        const wState = String(this.wrapper?.state || "").toLowerCase();
        if (wState) return wState === "active";
        return String(this.state || "").toLowerCase() === "active";
    }

    setSpinTransactionActive(isActive) {
        this._isSpinTransactionActive = Boolean(isActive);
    }

    // -------------------------------------------------------
    // State handling
    // -------------------------------------------------------
    onPause() {
        console.log("[GW] Game paused");
        this.state = "paused";
    }

    onResume() {
        console.log("[GW] Game resumed");
        this.state = "active";
    }

    extractEventDetail(evt) {
        if (evt && typeof evt === "object" && Object.prototype.hasOwnProperty.call(evt, "detail")) {
            return evt.detail;
        }
        return evt;
    }

    applySoundVolume(raw) {
        const detail = (raw && typeof raw === "object") ? (raw.volume ?? raw.value ?? raw) : raw;
        const vol = Math.max(0, Math.min(1, Number(detail)));
        if (!Number.isFinite(vol)) return;
        this.soundVolume = vol;
        try { nc?.sounds?.setMasterVolume?.(vol); } catch (_) {}
        try { nc?.sounds?.setVolume?.(vol); } catch (_) {}
    }

    // -------------------------------------------------------
    // Lifecycle helpers
    // -------------------------------------------------------
    gameStart() {
        this.wrapper?.dispatchEvent("gameStart");
    }

    gameEnd() {
        this.wrapper?.dispatchEvent("gameEnd");
    }

    gameReady() {
        if (this._gameReadySent) {
            console.log("[GW] gameReady() skipped - already emitted");
            return false;
        }

        this._gameReadySent = true;
        this.setLoadingProgress(1);
        this.hideLoadingBrand();
        this.wrapper?.gameReady?.();
        this.state = "active";
        console.log("[GW] gameReady()");

        // Fire-and-forget: never await this here. Deferred tiers (today just
        // tier 200, the Mystery Grab celebration frames) load AFTER the splash
        // is already gone -- see ProjectSettings.DEFERRED_LOADING_TIERS.
        this.beginBackgroundDeferredLoad();
        return true;
    }

    /**
     * Kicks off every configured deferred loading tier in the background.
     * Idempotent and safe to call more than once. Deliberately NOT awaited by
     * its caller (gameReady()) -- unlike the reverted 2026-09-04 attempt,
     * deferred tiers must never be able to delay hideSplash()/first paint.
     * Failures are logged, never thrown, so nothing downstream ever hangs on
     * a tier that failed to load.
     * @returns {Promise<void>} resolves once every configured tier has
     * settled (loaded or failed) -- awaited by awaitDeferredAssetsReady().
     */
    beginBackgroundDeferredLoad() {
        if (this._deferredLoadPromise) return this._deferredLoadPromise;
        const tiers = (window.ProjectSettings && ProjectSettings.DEFERRED_LOADING_TIERS) || [];
        this._deferredLoadPromise = (async () => {
            for (const tier of tiers) {
                try {
                    nc.loadTier(tier);
                    await nc.awaitLoadedTiers(tier);
                    console.log(`[GW] Deferred tier ${tier} finished loading in background.`);
                } catch (err) {
                    console.warn(`[GW] Deferred tier ${tier} failed to load:`, err);
                }
            }
        })();
        return this._deferredLoadPromise;
    }

    /**
     * Resolves once every deferred tier has settled (loaded or failed --
     * failures are swallowed by beginBackgroundDeferredLoad(), so this never
     * rejects). Await this immediately before using any asset that lives in a
     * deferred tier, so an unlucky early trigger (e.g. a player's very first
     * ticket landing a Mystery Grab win before the background load finishes)
     * waits a beat instead of rendering a missing texture.
     */
    async awaitDeferredAssetsReady() {
        await this.beginBackgroundDeferredLoad();
    }

    setLoadingProgress(progress) {
        const value = Math.max(0, Math.min(1, Number(progress)));
        if (Number.isNaN(value)) return;
        this.wrapper?.ui?.setLoaderProgress?.(value);
    }

    waitForUiReady() {
        return this.wrapper?.ui?.ready || Promise.resolve();
    }

    async ensureMinimumLoadingScreenDuration(minDurationMs) {
        const minMs = Number.isFinite(minDurationMs) ? minDurationMs : this.loadingScreenMinMs;
        const start = this.loadingScreenStartedAt || performance.now();
        const elapsed = Math.max(0, performance.now() - start);
        const remaining = Math.max(0, minMs - elapsed);
        if (remaining <= 0) return;
        await new Promise(resolve => setTimeout(resolve, remaining));
    }

    // -------------------------------------------------------
    // UI layout helpers
    // -------------------------------------------------------
    ensureWrapperUiOnTop() {
        const apply = () => {
            const root = document.getElementById("gamewrapper");
            if (!root) return false;
            root.style.position = "fixed";
            root.style.top = root.style.left = "0";
            root.style.width = root.style.height = "100%";
            root.style.zIndex = String(ProjectSettings.WRAPPER_Z_INDEX);
            root.style.pointerEvents = "auto";
            return true;
        };
        if (apply()) return;
        let tries = 0;
        const t = setInterval(() => { tries++; if (apply() || tries >= ProjectSettings.LAYOUT_RETRY_MAX_ATTEMPTS) clearInterval(t); }, ProjectSettings.LAYOUT_RETRY_INTERVAL_MS);
    }

    ensureBottomBarBelowCanvas() {
        const apply = () => {
            const view = document.getElementById("gw-view");
            const game = document.getElementById("gw-game");
            const bar  = document.getElementById("gw-bottom-bar");
            if (!view || !game || !bar) return false;

            const canvas = document.querySelector("#game_canvas canvas")
                || document.querySelector("canvas#game_canvas")
                || document.getElementById("game_canvas")
                || game.querySelector("canvas");

            view.style.display = "flex";
            view.style.flexDirection = "column";
            view.style.height = "100%";
            view.style.overflow = "hidden";

            game.style.flex = "1 1 auto";
            game.style.minHeight = "0";
            game.style.position = "relative";
            game.style.overflow = "hidden";

            bar.style.position = "static";
            bar.style.flex = "0 0 auto";
            bar.style.bottom = "auto";

            const rect = canvas?.getBoundingClientRect?.() || game.getBoundingClientRect();
            if (rect?.width > 0) {
                const w = `${Math.round(rect.width)}px`;
                bar.style.width = bar.style.minWidth = bar.style.maxWidth = w;
                bar.style.marginLeft = bar.style.marginRight = "auto";
                bar.style.alignSelf = "center";
            }

            const barH = Math.ceil(bar.getBoundingClientRect()?.height || 0);
            const pad  = Math.max(0, barH + (Number(this.bottomBarScreenPadding) || 0));
            if (this._appliedCanvasBottomPaddingPx !== pad) {
                this._appliedCanvasBottomPaddingPx = pad;
                window.__gwBottomPaddingPx = pad;
                window.dispatchEvent(new Event("resize"));
            }
            return true;
        };

        if (apply()) return;
        let tries = 0;
        const t = setInterval(() => { tries++; if (apply() || tries >= ProjectSettings.LAYOUT_RETRY_MAX_ATTEMPTS) clearInterval(t); }, ProjectSettings.LAYOUT_RETRY_INTERVAL_MS);
        if (!this._gwBottomBarResizeHandler) {
            this._gwBottomBarResizeHandler = () => apply();
            window.addEventListener("resize", this._gwBottomBarResizeHandler);
        }
    }

    ensureBottomBarControlsVisible() {
        const apply = () => {
            const bar = document.getElementById("gw-bottom-bar");
            if (!bar) return false;
            const tools = bar.querySelector("#gw-tools");
            if (tools) {
                tools.classList.remove("hidden");
                tools.style.display = "block";
                tools.style.visibility = "visible";
            }
            ["gw-btnLobby", "gw-btnSound"].forEach(cls => {
                const el = bar.querySelector(`.${cls}`);
                if (!el) return;
                el.classList.remove("hidden");
                el.style.display = "inline-block";
                el.style.visibility = "visible";
                const icon = el.querySelector(".gw-icon");
                if (icon) { icon.style.display = "inline-block"; icon.style.visibility = "visible"; }
            });
            return true;
        };
        if (apply()) return;
        let tries = 0;
        const t = setInterval(() => { tries++; if (apply() || tries >= ProjectSettings.LAYOUT_RETRY_MAX_ATTEMPTS) clearInterval(t); }, ProjectSettings.LAYOUT_RETRY_INTERVAL_MS);
    }

    ensureLoadingBrandVisible() {
        const applyBrand = () => {
            const wrapperRoot = document.getElementById("gamewrapper");
            if (!wrapperRoot) return false;

            let brand = document.getElementById("gw-loading-brand");
            if (!brand) {
                brand = document.createElement("div");
                brand.id = "gw-loading-brand";
                brand.innerHTML = [
                    '<div class="gw-loading-brand-inner">',
                    '<span class="gw-loading-brand-label">Powered by</span>',
                    '<span class="gw-provider-logo" aria-hidden="true"></span>',
                    '</div>'
                ].join("");
                wrapperRoot.appendChild(brand);
            }

            const base = (this.wrapperBasePath || "./libs/gamewrapper").replace(/\/$/, "");
            const logoUrl = `${base}/img/gromada_logo.png`;
            const logo = brand.querySelector(".gw-provider-logo");
            const inner = brand.querySelector(".gw-loading-brand-inner");
            const label = brand.querySelector(".gw-loading-brand-label");

            brand.style.position = "absolute";
            brand.style.left = "50%";
            brand.style.bottom = "1em";
            brand.style.transform = "translateX(-50%)";
            brand.style.zIndex = "30";
            brand.style.pointerEvents = "none";

            inner.style.height = "2em";
            inner.style.padding = "0 0.75em";
            inner.style.borderTop = "1px solid #2e2c2c";
            inner.style.background = "linear-gradient(#121213, #212327)";
            inner.style.color = "#7d7d7d";
            inner.style.font = "bold 12px/2em 'Roboto', sans-serif";
            inner.style.textTransform = "uppercase";
            inner.style.display = "flex";
            inner.style.alignItems = "center";
            inner.style.gap = "0.4em";

            label.style.whiteSpace = "nowrap";

            logo.style.backgroundImage = `url('${logoUrl}')`;
            logo.style.backgroundSize = "contain";
            logo.style.backgroundRepeat = "no-repeat";
            logo.style.backgroundPosition = "center";
            logo.style.height = "1em";
            logo.style.width = "2em";
            logo.style.display = "inline-block";

            return true;
        };

        if (applyBrand()) return;
        let tries = 0;
        this._gwLoadingBrandTimer = setInterval(() => {
            tries++;
            if (applyBrand() || tries >= ProjectSettings.LAYOUT_RETRY_MAX_ATTEMPTS) {
                clearInterval(this._gwLoadingBrandTimer);
                this._gwLoadingBrandTimer = null;
            }
        }, ProjectSettings.LAYOUT_RETRY_INTERVAL_MS);
    }

    hideLoadingBrand() {
        const brand = document.getElementById("gw-loading-brand");
        if (brand) brand.remove();
        if (this._gwLoadingBrandTimer) {
            clearInterval(this._gwLoadingBrandTimer);
            this._gwLoadingBrandTimer = null;
        }
    }

    // -------------------------------------------------------
    // Dashboard helpers
    // -------------------------------------------------------
    formatAmount(amount, trimFraction = false) {
        let formatted;
        if (this.wrapper?.formatCurrency) {
            try { formatted = this.wrapper.formatCurrency(Number(amount), trimFraction); } catch (_) {}
        }
        if (formatted === undefined || formatted === null) {
            const num = Number(amount) || 0;
            formatted = trimFraction ? ("$" + num.toFixed(0)) : ("$" + num.toFixed(2));
        }
        // No comma-glyph asset exists yet in the digit-sprite set (cb_num_0-9,
        // cb_dot, cb_dollar only -- see DashboardController.getAssetForChar()).
        // Until one is added, strip thousands separators here so the sprite
        // renderer does not silently drop the comma and misalign the digits
        // after it (or shift the centring math in renderValue()).
        return String(formatted).replace(/,/g, "");
    }

    /**
     * Current jurisdiction code, read straight from the ?jurisdiction= URL
     * param (the same key libs/gamewrapper reads as params['jurisdiction']
     * to pick which jurisdiction/<code>.json to load). Works identically
     * whether the real wrapper is running or not (LocalRgs standalone mode
     * included), since it never depends on the wrapper's own async
     * jurisdictionReady/gameJurisdiction -- see ProjectSettings.js's
     * WIN_CELEBRATION_GATED_JURISDICTIONS for the one place this is used.
     * Returns lowercase, or null if the param is absent.
     */
    getJurisdictionCode() {
        try {
            const code = new URLSearchParams(window.location.search).get('jurisdiction');
            return code ? code.toLowerCase() : null;
        } catch (_err) {
            return null;
        }
    }

    /**
     * Whether the current jurisdiction requires gating the "You Won!"
     * banner/SFX for a win <= the total bet (see ProjectSettings.js's
     * WIN_CELEBRATION_GATED_JURISDICTIONS doc comment). Defaults to false
     * for an empty/unrecognised jurisdiction -- including NJ, the only one
     * actually shipped today -- so every win celebrates unless a market
     * that needs the gate is explicitly configured.
     */
    requiresWinCelebrationGate() {
        const code = this.getJurisdictionCode();
        if (!code) return false;
        const gated = Array.isArray(ProjectSettings?.WIN_CELEBRATION_GATED_JURISDICTIONS)
            ? ProjectSettings.WIN_CELEBRATION_GATED_JURISDICTIONS
            : [];
        return gated.includes(code);
    }

    updateBalanceDisplay(balance) {
        const dc = pr?.dashboardController;
        if (!dc) return;
        const formatted = this.formatAmount(balance);
        dc.meters.balance.value = formatted;
        dc.updateDisplay("balance", formatted);
    }

    updateWinDisplay(winAmount) {
        const dc = pr?.dashboardController;
        if (!dc) return;
        const formatted = this.formatAmount(winAmount);
        dc.meters.win.value = formatted;
        dc.updateDisplay("win", formatted);
    }

    updateBetDisplay(bet) {
        const dc = pr?.dashboardController;
        if (!dc) return;
        const formatted = this.formatAmount(bet);
        dc.meters.bet.value = formatted;
        dc.updateDisplay("bet", formatted);
        if (this.wrapper?.setBet && !this._isSyncingStake) {
            try {
                this._isSyncingStake = true;
                this.wrapper.setBet(Number(bet));
            } catch (_) {}
            finally { this._isSyncingStake = false; }
        }
    }

    // -------------------------------------------------------
    // Error handling
    // -------------------------------------------------------
    onError(error) {
        console.error("[GW ERROR]", error);
        this.state = "error";

        const mapped = this.mapError(error);
        try {
            this.wrapper?.ui?.showMessage?.({
                title: mapped.title,
                text: mapped.message
            });
        } catch (messageError) {
            console.warn("[GW] Failed to show wrapper error message:", messageError);
        }
    }

    mapError(error) {
        const code = String(
            error?.code
            || error?.error
            || error?.name
            || error?.message
            || error
            || ""
        ).trim().toLowerCase();

        switch (code) {
            case "requestblocked":
                return {
                    title: "Request Paused",
                    message: "Please resume the game before continuing.",
                    actions: ["ok"]
                };
            case "unsettledticketexists":
                return {
                    title: "Unsettled Ticket Found",
                    message: "Please settle the previous ticket before starting a new one.",
                    actions: ["ok"]
                };
            case "insufficient_balance":
                return {
                    title: "Not Enough Balance",
                    message: "Please lower your bet or add funds.",
                    actions: ["ok"]
                };
            case "network_error":
                return {
                    title: "Connection Problem",
                    message: "Please check your internet connection.",
                    actions: ["retry"]
                };
            case "gamewrapper_init_error":
            case "gamewrapper.init error":
                return {
                    title: "Initialization Failed",
                    message: "Game wrapper initialization failed. Please reload the game.",
                    actions: ["reload"]
                };
            default:
                return {
                    title: "Something Went Wrong",
                    message: "Please try again or reload the game.",
                    actions: ["retry", "reload"]
                };
        }
    }

    onErrorAction(action) {
        switch (action) {
            case "retry":
                this.retryLastAction();
                break;
            case "reload":
                window.location.reload();
                break;
        }
    }

    retryLastAction() {
        if (!this.lastAction) return;
        const actionType = typeof this.lastAction === "string"
            ? this.lastAction
            : this.lastAction.type;
        console.log("[GW] Retrying last action:", actionType);
        // For fixed-odds, there's no spin retry; only stake change
        if (actionType === "STAKE_CHANGE") {
            this.onStakeChange({ stake: this.lastAction.stake });
        }
    }

    onConnectionLost() {
        this.state = "error";
        try {
            this.wrapper?.ui?.showMessage?.({
                title: "Connection Lost",
                text: "Reconnecting..."
            });
        } catch (_e) {}
    }

    onConnectionRestored() {
        this.state = "active";
    }

    // -------------------------------------------------------
    // PostMessage registration
    // -------------------------------------------------------
    registerPostMessage() {
        if (this._boundPostMessageHandler) return;
        this._boundPostMessageHandler = this.onPostMessage.bind(this);
        window.addEventListener("message", this._boundPostMessageHandler);
    }

    parsePostMessagePayload(rawData) {
        let payload = rawData;
        if (typeof payload === "string") {
            try { payload = JSON.parse(payload); } catch (_err) { return null; }
        }
        if (!payload || typeof payload !== "object") return null;
        return payload;
    }

    async refreshAccountFromPostMessage() {
        try {
            const account = await this.callRgsMethod("getAccount");
            if (account && account.balance !== undefined) {
                this.updateBalanceDisplay(Number(account.balance));
            }
        } catch (error) {
            console.warn("[GW] updatePlayer/getAccount failed:", error);
        }
    }

    handleWrapperPostMessage(name, data) {
        switch (name) {
            case "betStops":
                this.onStakeLimits(data || {});
                break;
            case "volume":
                this.applySoundVolume(data?.volume);
                break;
            case "mute":
                nc.sounds.setMute(true);
                if (pr.audioController) pr.audioController.mute();
                break;
            case "unmute":
                nc.sounds.setMute(false);
                if (pr.audioController) pr.audioController.unmute();
                break;
            case "updatePlayer":
                void this.refreshAccountFromPostMessage();
                break;
            case "accountData":
                if (Number.isFinite(Number(data?.balance))) {
                    this.updateBalanceDisplay(Number(data.balance));
                }
                break;
            case "gameReady":
            case "gameStart":
            case "gameEnd":
            case "bonusStart":
            case "bonusEnd":
            case "outOfCoins":
            case "toLobby":
            case "toLubby":
            case "error":
                break;
            default:
                break;
        }
    }

    onPostMessage(event) {
        if (!this.isAllowedOrigin(event.origin)) return;

        const msg = this.parsePostMessagePayload(event.data);
        if (!msg) return;

        if (typeof msg.name === "string") {
            this.handleWrapperPostMessage(msg.name, msg.data || {});
            return;
        }

        if (msg.type === "COMMAND") {
            console.log("[postMessage][COMMAND]", msg.action);
            switch (msg.action) {
                case "pause": this.onPause(); break;
                case "resume": this.onResume(); break;
                case "set-stake": this.onStakeChange(msg.payload); break;
                case "mute": nc.sounds.setMute(true); break;
                case "unmute": nc.sounds.setMute(false); break;
                default: break;
            }
        }
    }

    isAllowedOrigin(origin) {
        if (origin === "null") return true;
        return this.allowedOrigins.includes(origin);
    }

    postToParent(action, payload = {}) {
        window.parent.postMessage({ type: "EVENT", action, payload }, "*");
    }

    postWrapperMessage(name, data = {}) {
        try {
            window.parent.postMessage(JSON.stringify({ name, data }), "*");
        } catch (error) {
            console.warn("[GW] postWrapperMessage failed:", error);
        }
    }
}

window.GameWrapperManager = GameWrapperManager;
